{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "Lightbox",
    "displayName": "Lightbox",
    "category": "Overlay",
    "keywords": [
      "lightbox",
      "image",
      "video",
      "viewer",
      "gallery",
      "zoom",
      "fullscreen",
      "media",
      "photo",
      "preview"
    ],
    "props": [
      {
        "name": "isOpen",
        "type": "boolean",
        "description": "Whether the lightbox is open.",
        "required": true
      },
      {
        "name": "onOpenChange",
        "type": "(isOpen: boolean) => void",
        "description": "Callback when the lightbox open state changes: the Close button, Escape, a tap beside the media, or, on a phone or tablet, dragging a photo down from its fitted size.",
        "required": true
      },
      {
        "name": "media",
        "type": "LightboxMedia | LightboxMedia[]",
        "description": "Media to display. Pass a single object for one item, or an array for gallery mode with prev/next navigation (on a phone or tablet, a swipe moves between items too). Each item is {src: string, alt: string, caption?: ReactNode, type?: 'image' | 'video'}; type defaults to 'image', and zoom/pan is disabled for 'video'.",
        "required": true
      },
      {
        "name": "index",
        "type": "number",
        "description": "Current index in gallery mode (when media is an array)."
      },
      {
        "name": "onIndexChange",
        "type": "(index: number) => void",
        "description": "Callback when the gallery index changes: prev/next, the arrow keys, or a swipe."
      },
      {
        "name": "hasZoom",
        "type": "boolean",
        "description": "Enable zoom (images only): pinch (or ctrl-wheel), or double-tap or double-click to zoom in at that point and back; Enter/Space/+/- zoom 2× about the centre and back, and 0 returns to the fitted size. When zoomed, drag or scroll a trackpad to pan, or use arrow keys; on a phone or a tablet, the pan has momentum.",
        "default": "false"
      },
      {
        "name": "defaultIndex",
        "type": "number",
        "description": "Initial image index in gallery mode for uncontrolled usage.",
        "default": "0"
      },
      {
        "name": "hasAutoPlay",
        "type": "boolean",
        "description": "Automatically start video playback when a video media item is shown.",
        "default": "false"
      },
      {
        "name": "xstyle",
        "type": "StyleXStyles",
        "description": "StyleX styles for layout customization. Must be stylex.create() value."
      }
    ],
    "theming": {
      "targets": [
        {
          "className": "astryx-lightbox",
          "visualProps": []
        }
      ]
    },
    "usage": {
      "anatomy": [
        {
          "name": "Viewer overlay",
          "required": true,
          "description": "Full-viewport dialog overlay that contains the active media and controls."
        },
        {
          "name": "Media",
          "required": true,
          "description": "Active image or video presented inside the viewer."
        },
        {
          "name": "Close button",
          "required": true,
          "description": "Button that closes the viewer."
        },
        {
          "name": "Previous button",
          "required": false,
          "description": "Gallery button that moves to the previous media item."
        },
        {
          "name": "Next button",
          "required": false,
          "description": "Gallery button that moves to the next media item."
        },
        {
          "name": "Caption",
          "required": false,
          "description": "Caller-provided caption displayed below the active media."
        },
        {
          "name": "Counter",
          "required": false,
          "description": "Current position and total shown in gallery mode."
        }
      ],
      "description": "A fullscreen overlay for viewing images and videos at full resolution. Supports single-item and gallery modes with prev/next navigation and swiping, optional zoom and pan for images, and native video controls.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Always provide alt text for every image for screen reader accessibility."
        },
        {
          "guidance": true,
          "description": "Use gallery mode with onIndexChange for multi-image sets."
        },
        {
          "guidance": true,
          "description": "Enable hasZoom only when viewing high-resolution images that benefit from close inspection."
        },
        {
          "guidance": false,
          "description": "Use the lightbox for content other than images and videos; it shows one media item at a time."
        },
        {
          "guidance": false,
          "description": "Nest interactive content inside captions; keep them plain text."
        }
      ]
    },
    "playground": {
      "overlay": true,
      "defaults": {
        "isOpen": false,
        "media": {
          "src": "/template-assets/light-scene-horizontal-1.png",
          "alt": "Coastal shoreline with ocean waves",
          "caption": "A scenic coastline with waves rolling onto a sandy beach beneath a clear sky."
        }
      }
    },
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/Lightbox",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
